SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
SET SQL_MODE = 'NO_AUTO_VALUE_ON_ZERO';

USE hospital;

CREATE TABLE IF NOT EXISTS patients (
	id INTEGER NOT NULL, 
	name VARCHAR(100), 
	tracking_id VARCHAR(50) NOT NULL, 
	entry_time DATETIME NOT NULL, 
	exit_time DATETIME, 
	status VARCHAR(7) NOT NULL, 
	current_zone VARCHAR(50), 
	created_at DATETIME, 
	updated_at DATETIME, mobile VARCHAR(20), last_action VARCHAR(200), 
	PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS zones (
	id INTEGER NOT NULL, 
	zone_name VARCHAR(50) NOT NULL, 
	display_name VARCHAR(100), 
	description VARCHAR(255), 
	capacity_limit INTEGER NOT NULL, 
	current_occupancy INTEGER, 
	zone_type VARCHAR(50), 
	floor_number INTEGER, 
	building VARCHAR(100), 
	warning_threshold FLOAT, 
	critical_threshold FLOAT, 
	is_active TINYINT(1), 
	created_at DATETIME, 
	updated_at DATETIME, 
	PRIMARY KEY (id),
	UNIQUE KEY (zone_name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS alerts (
	id INTEGER NOT NULL, 
	timestamp DATETIME NOT NULL, 
	alert_type VARCHAR(17) NOT NULL, 
	severity VARCHAR(8) NOT NULL, 
	message TEXT NOT NULL, 
	zone_name VARCHAR(50), 
	patient_id INTEGER, 
	is_active TINYINT(1), 
	acknowledged TINYINT(1), 
	acknowledged_at DATETIME, 
	acknowledged_by VARCHAR(100), 
	resolved_at DATETIME, 
	metadata_json TEXT, 
	PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS metrics (
	id INTEGER NOT NULL, 
	timestamp DATETIME NOT NULL, 
	period_start DATETIME, 
	period_end DATETIME, 
	metric_type VARCHAR(50), 
	zone_name VARCHAR(50), 
	avg_dwell_time FLOAT, 
	min_dwell_time FLOAT, 
	max_dwell_time FLOAT, 
	entry_rate FLOAT, 
	exit_rate FLOAT, 
	throughput FLOAT, 
	total_entries INTEGER, 
	total_exits INTEGER, 
	peak_occupancy INTEGER, 
	avg_occupancy FLOAT, 
	sample_count INTEGER, 
	PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS occupancy_logs (
	id INTEGER NOT NULL, 
	timestamp DATETIME NOT NULL, 
	people_count INTEGER NOT NULL, 
	previous_count INTEGER, 
	zone_name VARCHAR(50) NOT NULL, 
	entry_count INTEGER, 
	exit_count INTEGER, 
	confidence_score FLOAT, 
	source VARCHAR(50), 
	PRIMARY KEY (id), 
	FOREIGN KEY(zone_name) REFERENCES zones (zone_name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE UNIQUE INDEX ix_patients_tracking_id ON patients (tracking_id);
CREATE INDEX ix_patients_current_zone ON patients (current_zone);
CREATE INDEX ix_patients_status_zone ON patients (status, current_zone);
CREATE INDEX ix_patients_id ON patients (id);
CREATE UNIQUE INDEX ix_zones_zone_name ON zones (zone_name);
CREATE INDEX ix_zones_id ON zones (id);
CREATE INDEX ix_alerts_timestamp ON alerts (timestamp);
CREATE INDEX ix_alerts_zone_name ON alerts (zone_name);
CREATE INDEX ix_alerts_id ON alerts (id);
CREATE INDEX ix_alerts_alert_type ON alerts (alert_type);
CREATE INDEX ix_metrics_zone_name ON metrics (zone_name);
CREATE INDEX ix_metrics_metric_type ON metrics (metric_type);
CREATE INDEX ix_metrics_timestamp ON metrics (timestamp);
CREATE INDEX ix_metrics_id ON metrics (id);
CREATE INDEX ix_occupancy_logs_id ON occupancy_logs (id);
CREATE INDEX ix_occupancy_logs_timestamp ON occupancy_logs (timestamp);
CREATE INDEX ix_occupancy_logs_zone_name ON occupancy_logs (zone_name);

SET FOREIGN_KEY_CHECKS = 1;
